def backfill_issued(apps, schema_editor):
    """Certificados emitidos antes da auditoria ganham o evento "Emitido" com a data original."""
    Certificate = apps.get_model('certificates', 'Certificate')
    Event = apps.get_model('certificates', 'CertificateEvent')

    def actor_name(user):
        full = f'{user.first_name} {user.last_name}'.strip()
        return f'{full} ({user.username})' if full else user.username

    events = []
    qs = Certificate.objects.select_related('batch__created_by', 'registration__activity__organizer')
    for c in qs.iterator():
        actor = c.batch.created_by if c.batch_id else c.registration.activity.organizer
        events.append(
            Event(
                created_at=c.issued_at,
                action='ISSUED',
                certificate=c,
                batch_id=c.batch_id,
                actor=actor,
                actor_name=actor_name(actor),
                code=c.code,
                participant_name=c.participant_name,
                participant_document=c.participant_document,
                activity_title=c.activity_title,
                details={'source': 'Emissão avulsa' if c.batch_id else 'Atividade do sistema', 'backfill': True},
            )
        )
    Event.objects.bulk_create(events, batch_size=1000)


